from collections import deque

def bfs(start, graph):
    visited = set()
    queue = deque([start])
    visited.add(start)  # 注意这里！！！BFS 只要无脑在入队时标记时就可以了，防止重复入队

    while queue:
        node = queue.popleft()
        print(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor) # 注意这里！！！同上
                queue.append(neighbor)
